<script lang="ts">
import {tick} from 'svelte';import Icon from './Icon.svelte';import {stamp} from './statistics';import type {OfficeHistory} from './bridge';
let {offices,language,t}:{offices:OfficeHistory[];language:string;t:(key:string)=>string}=$props();let active=$state<string|null>(null);let expanded=$state<string|null>(null);let root:HTMLDivElement;let popup=$state<HTMLDivElement>();let position=$state({left:0,top:0});
async function reveal(label:string,element:HTMLElement){active=label;await tick();if(active!==label||!popup)return;popup.showPopover?.();const rect=element.getBoundingClientRect();const height=popup.getBoundingClientRect().height;position={left:Math.max(8,Math.min(rect.right-270,window.innerWidth-278)),top:rect.bottom+height<window.innerHeight-8?rect.bottom:Math.max(8,rect.top-height)};}
function parts(label:string){const comma=label.indexOf(',');return comma<0?[label,'']:[label.slice(0,comma),label.slice(comma+1).trim()];}
</script>
<svelte:window onpointerdown={event=>{if(!root?.contains(event.target as Node))active=null;}} onkeydown={event=>{if(event.key==='Escape')active=null;}}/>
<div class="office-history" bind:this={root}>{#each offices as office(office.label)}{@const words=parts(office.label)}<article class="office-entry"><div class="office-words"><strong>{words[0]}</strong>{#if words[1]}<span class="muted">{words[1]}</span>{/if}<small class="muted">{office.last_seen?stamp(office.last_seen,language):t('Дата неизвестна')}</small></div><div class="office-count" role="group" onpointerenter={event=>void reveal(office.label,event.currentTarget)} onpointerleave={()=>active=null}><button type="button" class="flat count-button" aria-expanded={active===office.label} onfocus={event=>void reveal(office.label,event.currentTarget)} onblur={event=>{if(!(event.currentTarget.parentElement?.contains(event.relatedTarget as Node)))active=null;}} onclick={event=>void reveal(office.label,event.currentTarget)}>{office.count===null?t('Количество неизвестно'):t('Появлений: {count}').replace('{count}',new Intl.NumberFormat(language).format(office.count))}</button>{#if active===office.label}<div class="office-popover" popover="manual" bind:this={popup} style:left={`${position.left}px`} style:top={`${position.top}px`} role="region" aria-label={t('Появления офиса')}><strong>{t('Появления офиса')}</strong>{#each office.appearances.slice(-5).reverse() as appearance}<span>{stamp(appearance.time,language)}</span>{:else}<span class="muted">{t('Время появлений не сохранено')}</span>{/each}{#if office.appearances.length>5}<button class="flat" type="button" onclick={()=>{expanded=office.label;active=null;}}>{t('Все появления')}</button>{/if}</div>{/if}</div>{#if expanded===office.label}<div class="office-all"><button class="icon-button" title={t('Закрыть')} aria-label={t('Закрыть')} onclick={()=>expanded=null}><Icon name="close"/></button>{#each office.appearances.slice().reverse() as appearance}<span>{stamp(appearance.time,language)}</span>{/each}</div>{/if}</article>{:else}<div class="office-empty"><Icon name="office" size={26}/><p>{t('Офисы пока не появлялись')}</p></div>{/each}</div>
<style>.office-entry{display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap;padding:16px 0;border-top:1px solid var(--line)}.office-words{display:grid;gap:5px;flex:1;min-width:220px}.office-words strong{font-weight:600}.office-words small{font-variant-numeric:tabular-nums}.office-count{position:relative}.count-button{padding:8px 0;color:var(--accent-text);border:0;background:none}.office-popover{position:fixed;inset:auto;margin:0;color:var(--text);width:270px;padding:14px;display:grid;gap:8px;z-index:5;background:var(--surface);border:1px solid var(--strong);border-radius:8px;box-shadow:0 8px 24px #0003;font-variant-numeric:tabular-nums}.office-popover strong{font-weight:600}.office-all{width:100%;position:relative;padding:10px 38px 10px 12px;border-radius:6px;background:var(--surface);display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;font-variant-numeric:tabular-nums}.office-all .icon-button{position:absolute;right:0;top:0}.office-empty{padding:32px;text-align:center;color:var(--muted)}.office-empty :global(svg){margin:auto}</style>
